    @Test
    void anUnknownReservationIsNotFound() {
        assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
    }

    @Test
    void confirmingNotifiesHousekeepingAndFinance() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));

        service.confirm(reservation.id());

        List<Message> sent = sentMessages.all();
        assertEquals(3, sent.size());
        Message housekeeping = sent.get(1);
        assertEquals("governanca@pousadamarealta.com.br", housekeeping.to());
        assertEquals("Reserva confirmada - quarto 201", housekeeping.subject());
        assertTrue(housekeeping.body().contains("10/03/2027"));
        assertTrue(housekeeping.body().contains("12/03/2027"));
        assertTrue(housekeeping.body().contains("2"));
        Message finance = sent.get(2);
        assertEquals("financeiro@pousadamarealta.com.br", finance.to());
        assertEquals("Pagamento recebido - reserva " + reservation.id(), finance.subject());
        assertTrue(finance.body().contains("R$ 779,80"));
    }

    @Test
    void cancellingAConfirmedReservationNotifiesHousekeepingAndFinance() {
        Reservation reservation = service.create(stay(202, "2027-03-15", "2027-03-18", 3, RatePlan.STANDARD));
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        List<Message> sent = sentMessages.all();
        assertEquals(6, sent.size());
        Message housekeeping = sent.get(4);
        assertEquals("governanca@pousadamarealta.com.br", housekeeping.to());
        assertEquals("Reserva cancelada - quarto 202", housekeeping.subject());
        assertTrue(housekeeping.body().contains("15/03/2027"));
        assertTrue(housekeeping.body().contains("18/03/2027"));
        Message finance = sent.get(5);
        assertEquals("financeiro@pousadamarealta.com.br", finance.to());
        assertEquals("Reembolso - reserva " + reservation.id(), finance.subject());
        assertTrue(finance.body().contains("R$ 1.169,70"));
    }

    @Test
    void cancellingAPendingReservationDoesNotNotifyAnyone() {
        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD));

        service.cancel(reservation.id());

        assertEquals(0, sentMessages.all().size());
    }

    @Test
    void cancellingANonRefundableReservationDoesNotNotifyFinance() {
        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        List<Message> sent = sentMessages.all();
        assertEquals(4, sent.size());
        assertEquals("governanca@pousadamarealta.com.br", sent.get(3).to());
        assertEquals("Reserva cancelada - quarto 101", sent.get(3).subject());
    }
}

